import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] jobs = new long[(int) n][3];
        for (int i = 0; i < jobs.length; i++) {
            for (int j = 0; j < jobs[i].length; j++) {
                jobs[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        long[] keys = new long[cn];
        for (int i = 0; i < cn; i++) keys[i] = (jobs[i][1] << 15) | i;
        Arrays.sort(keys);
        long[] ends = new long[cn], starts = new long[cn], profit = new long[cn];
        for (int i = 0; i < cn; i++) {
            int id = (int) (keys[i] & 32767L);
            ends[i] = jobs[id][1];
            starts[i] = jobs[id][0];
            profit[i] = jobs[id][2];
        }
        long[] best = new long[cn + 1];
        for (int i = 0; i < cn; i++) {
            int lo = 0, hi = i;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (ends[mid] <= starts[i]) lo = mid + 1;
                else hi = mid;
            }
            best[i + 1] = Math.max(best[i], best[lo] + profit[i]);
        }
        System.out.println(best[cn]);
    }
}
